import {calculate} from './core.js';
import {bargain} from './bargain.js';
const $=s=>document.querySelector(s),money=v=>'¥'+(v/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
$('#calculator-view').innerHTML='<div class="calculator-grid"><section class="card calculator"><div class="card-heading"><div><h2>手续费／还价试算</h2><p>把平台扣费、额外补差和双方实际收支算清楚。</p></div></div><label>计算模式<select id="calc-mode"><option value="net">挂价 → 净到手</option><option value="gross">目标到手 → 所需挂价</option><option value="bargain">还价＋补差额试算</option></select></label><label><span id="amount-label">挂牌价 / 元</span><input id="amount" type="number" min="0" step="0.01" value="3000"></label><div id="bargain-fields" hidden><label>输入口径<select id="bargain-source"><option value="quote">按原挂价</option><option value="target">按卖家目标到手反推原挂价</option></select></label><label>平台还价金额 / 元<input id="offer" type="number" min="0" step="0.01" value="2400"></label><div class="fee-shortcuts"><button type="button" data-discount="0.8">一键8折</button><button type="button" data-discount="0.9">一键9折</button><span id="discount-display"></span></div><label>手续费差额归属<select id="fee-share"><option value="1">归买家 · 卖家到手不变</option><option value="0.5">双方各半</option><option value="0">归卖家 · 买家总支出不变</option></select></label></div><details class="fee-rule"><summary>费用规则 <span id="fee-rule-label">参考预设 · 可调整</span></summary><div class="two-col"><label>卖家费率 / %<input id="rate" type="number" min="0" max="99.99" step="0.01" value="8"></label><label>最低手续费 / 元<input id="fee-min" type="number" min="0" step="0.01" value="0"></label></div><div class="two-col"><label>手续费封顶 / 元（留空不封顶）<input id="fee-max" type="number" min="0" step="0.01" placeholder="不封顶"></label><label>其他卖家费用 / 元<input id="extra" type="number" min="0" step="0.01" value="0"></label></div><label>设定的最低还价比例 / %<input id="min-offer" type="number" min="0" max="100" step="0.01" value="80"></label><p>8%费率、8折下限是参考工具的预设，可按实际规则修改；不代表已核实的平台固定规则。</p></details><label id="cost-label">买入总成本 / 元（可选，用于盈亏）<input id="cost" type="number" min="0" step="0.01" placeholder="输入真实买入成本"></label><p class="subtle-note">金额精确到分，手续费按分四舍五入。补差额仅作测算；平台外付款不在平台交易保障范围内。</p></section><section class="card calc-result"><div class="eyebrow">TRANSACTION ESTIMATE</div><h2 id="result-title">预计卖家净到手</h2><div id="result-value">—</div><div id="result-breakdown"></div><div id="fee-baseline"></div><p id="fee-message"></p><button type="button" class="button secondary" id="copy-fee">复制试算结果</button><textarea id="fee-summary" readonly aria-label="试算结果文本"></textarea></section></div>';
let discountLock=.8,lastResult=null;
function cents(id,optional=false){const value=$(id).value.trim();if(!value&&optional)return null;if(!/^\d+(?:\.\d{1,2})?$/.test(value))throw Error('金额需为非负数字，最多两位小数');const [a,b='']=value.split('.');const result=Number(a)*100+Number(b.padEnd(2,'0'));if(!Number.isSafeInteger(result)||result>1e12)throw Error('金额超出计算范围');return result}
function rule(){const rate=$('#rate').value.trim();if(!rate)throw Error('请填写费率');return {rate:Number(rate),min:cents('#fee-min'),max:cents('#fee-max',true),extra:cents('#extra')}}
function quoteValue(){const r=rule(),amount=cents('#amount');return $('#bargain-source').value==='target'?calculate(amount,r,true).price:amount}
function syncOffer(){if(discountLock==null)return;try{$('#offer').value=(Number((BigInt(quoteValue())*BigInt(Math.round(discountLock*10000))+9999n)/10000n)/100).toFixed(2)}catch{}}
function row(label,value){return `<div class="breakdown-row"><span>${label}</span><strong>${value}</strong></div>`}
function render(){
 const mode=$('#calc-mode').value,isBargain=mode==='bargain';$('#bargain-fields').hidden=!isBargain;$('#amount-label').textContent=mode==='gross'||(isBargain&&$('#bargain-source').value==='target')?'目标卖家净到手 / 元':'原挂牌价 / 元';$('#copy-fee').disabled=true;lastResult=null;
 try{
  const r=rule(),amount=cents('#amount');let rows=[],summary=[],headline;
  if(isBargain){const quote=quoteValue(),offer=cents('#offer'),minValue=$('#min-offer').value.trim();if(!minValue)throw Error('请填写最低还价比例');const result=bargain(quote,offer,r,Number($('#fee-share').value),Number(minValue)/100);headline=result.supplement;$('#result-title').textContent='买家需补差额（额外支付）';
   rows=[['原挂价',money(quote)],['平台成交价（还价）',money(offer)],['平台手续费',money(result.fee)],['买家实际总支出',money(result.buyerTotal)],['卖家实际净到手',money(result.sellerNet)],['手续费差额',money(result.saving)],['买家节省',money(result.buyerSaving)],['卖家增加到手',money(result.sellerGain)]];
   $('#fee-baseline').textContent=`原价成交基准：买家付 ${money(quote)}，卖家到手 ${money(result.originalNet)}。本次费率 ${r.rate}%。`;
   $('#discount-display').textContent=quote?`当前 ${(offer/quote*10).toFixed(4)} 折`:'零金额';
   const cost=cents('#cost',true);if(cost!=null)rows.push(['扣除买入成本后净收益',money(result.sellerNet-cost)]);
   summary=[`还价／补差试算（费率${r.rate}%）`,`分配：${$('#fee-share').selectedOptions[0].textContent}`,`额外补差：${money(result.supplement)}`];lastResult=result;
  }else{const result=calculate(amount,r,mode==='gross');headline=mode==='gross'?result.price:result.net;$('#result-title').textContent=mode==='gross'?'达到目标所需最低挂价':'预计卖家净到手';rows=[['成交挂价',money(result.price)],['平台手续费',money(result.fee)],['其他卖家费用',money(r.extra)],['预计净到手',money(result.net)]];const cost=cents('#cost',true);if(cost!=null)rows.push(['预计净收益',money(result.net-cost)],['保本挂价',money(calculate(cost,r,true).price)]);$('#fee-baseline').textContent='';summary=[`手续费试算（费率${r.rate}%）`];lastResult=result}
  $('#result-value').textContent=money(headline);$('#result-breakdown').innerHTML=rows.map(([label,value])=>row(label,value)).join('');$('#fee-message').textContent='基于当前填写规则计算，优惠、税款及未输入费用不自动纳入。';$('#fee-summary').value=[...summary,...rows.map(([a,b])=>a+'：'+b),'补差仅作测算，平台外付款不在平台保障范围内。'].join('\n');$('#copy-fee').disabled=false;
 }catch(error){$('#result-value').textContent='请检查输入';$('#result-breakdown').textContent=error.message;$('#fee-baseline').textContent='';$('#fee-summary').value='';$('#fee-message').textContent='修正输入后会自动重新计算。'}
}
$('#calc-mode').onchange=()=>{syncOffer();render()};$('#bargain-source').onchange=()=>{syncOffer();render()};
document.querySelectorAll('#calculator-view input,#calculator-view select').forEach(input=>{if(['calc-mode','bargain-source'].includes(input.id))return;input.oninput=()=>{if(input.id==='offer')discountLock=null;else if(['amount','rate','fee-min','fee-max','extra'].includes(input.id))syncOffer();render()}});
document.querySelectorAll('[data-discount]').forEach(button=>button.onclick=()=>{discountLock=Number(button.dataset.discount);syncOffer();render()});
$('#copy-fee').onclick=async()=>{if(!lastResult)return;try{await navigator.clipboard.writeText($('#fee-summary').value);$('#copy-fee').textContent='已复制'}catch{$('#fee-summary').focus();$('#fee-summary').select();$('#copy-fee').textContent='请复制已选中的结果'}setTimeout(()=>$('#copy-fee').textContent='复制试算结果',2500)};
window.addEventListener('fee-product',event=>{$('#amount').value=(event.detail/100).toFixed(2);$('#calc-mode').value='bargain';$('#bargain-source').value='quote';discountLock=.8;syncOffer();document.querySelector('[data-view="calculator"]').click();render()});render();
document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>{if(button.dataset.view==='calculator')location.hash='calculator';else if(location.hash==='#calculator')history.replaceState(null,'',location.pathname)}));
if(location.hash==='#calculator')document.querySelector('[data-view="calculator"]').click();
